def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    x, y = observation['self_position']
    obstacles = set(tuple(obs) for obs in observation.get('obstacles', []))
    resources = observation.get('resources', [])
    opponent_x, opponent_y = observation.get('opponent_position', (0,0))
    score_self = observation.get('scores', [0,0])[0]
    score_opp = observation.get('scores', [0,0])[1]
    remaining = observation.get('remaining_resource_count', 0)

    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    # Helper to check if position is within bounds and free
    def free(pos):
        px, py = pos
        return 0 <= px < wx and 0 <= py < wy and pos not in obstacles

    # Find closest resource
    res_pos = None
    min_d = float('inf')
    for r in resources:
        rp = tuple(r)
        d = dist((x,y), rp)
        if d < min_d:
            min_d = d
            res_pos = rp

    # Move towards target
    def move_towards(target):
        dx = dy = 0
        if target[0] > x:
            dx = 1
        elif target[0] < x:
            dx = -1
        if target[1] > y:
            dy = 1
        elif target[1] < y:
            dy = -1
        # Prefer horizontal if both options are possible
        if dx != 0 and dy != 0:
            # Try horizontal first
            if free((x + dx, y)):
                return dx, 0
            elif free((x, y + dy)):
                return 0, dy
            # Try vertical first
            elif free((x, y + dy)):
                return 0, dy
            elif free((x + dx, y)):
                return dx, 0
            else:
                return 0,0
        elif dx != 0:
            if free((x + dx, y)):
                return dx,0
            else:
                return 0,0
        elif dy != 0:
            if free((x, y + dy)):
                return 0,dy
            else:
                return 0,0
        else:
            return 0,0

    # If resource available, go for it
    if res_pos:
        return move_towards(res_pos)
    else:
        # If no resources, chase opponent if behind
        if score_self <= score_opp:
            return move_towards((opponent_x, opponent_y))
        else:
            # Else, wander or stay
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if free((nx, ny)):
                    return dx, dy
            return 0,0
